            var failure = sendStarted && exception is not PublishException
                ? PublicationFailure.AcceptanceUnknown : PublicationFailure.NotAccepted;
            throw new JobPublicationException(failure, exception);
        }
        finally
        {
            if (acquired) gate.Release();
        }
